CREATE TABLE IF NOT EXISTS mail_deliveries(id BIGINT AUTO_INCREMENT PRIMARY KEY,incident_id BIGINT UNSIGNED NOT NULL,recipient VARCHAR(254) NOT NULL,audience VARCHAR(20) NOT NULL,status VARCHAR(20) DEFAULT 'pending',attempts INT DEFAULT 0,last_error VARCHAR(255) NULL,next_attempt DATETIME DEFAULT CURRENT_TIMESTAMP,sent_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY incident_recipient(incident_id,recipient));
